// Title: How to verify that page orientation and fit‑to‑page settings are applied when converting an Excel worksheet to PDF with Aspose.Cells for .NET (C#)
// Common Searches: C# check PDF page orientation after exporting Excel with Aspose.Cells | verify fit to one page wide and tall setting in PDF generated by Aspose.Cells | how to confirm Aspose.Cells PDF export respects worksheet page setup in .NET | validate that landscape orientation is applied in PDF created from Excel using Aspose.Cells
// Tags: Aspose.Cells PDF generation layout verification | C# convert Excel worksheet to PDF landscape format | fit-to-page scaling Aspose.Cells PDF conversion | verify PDF output file presence .NET | worksheet layout mapping to PDF Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

// The example loads an Excel workbook (input.xlsx), sets the first worksheet's page orientation to landscape and configures it to fit to one page wide and tall, then saves the workbook as a PDF (output.pdf) using Aspose.Cells for .NET. After saving, it checks whether the PDF file was created and reports success or failure, handling any exceptions that may occur.
class PdfReview
{
    static void Main()
    {
        const string inputPath = "input.xlsx";
        const string outputPath = "output.pdf";

        try
        {
            // Ensure the input Excel file exists
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Input file not found: {inputPath}");
                return;
            }

            // Load the source workbook
            Workbook workbook = new Workbook(inputPath);

            // Configure page setup for the first worksheet
            Worksheet sheet = workbook.Worksheets[0];
            sheet.PageSetup.Orientation = PageOrientationType.Landscape;
            sheet.PageSetup.FitToPagesWide = 1;
            sheet.PageSetup.FitToPagesTall = 1;

            // Export the workbook to PDF
            workbook.Save(outputPath, SaveFormat.Pdf);
            Console.WriteLine($"Workbook saved as PDF: {outputPath}");

            // Verify that the PDF file was created
            if (File.Exists(outputPath))
            {
                Console.WriteLine("PDF file created successfully.");
            }
            else
            {
                Console.WriteLine("Failed to create PDF file.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
